class Contagem:
    def __init__(self, inicio):
        self.atual = inicio
    def __iter__(self):
        return self
    def __next__(self):
        if self.atual == 0:
            raise StopIteration
        self.atual -= 1
        return self.atual + 1

for n in Contagem(3):
    print(n)

