class Eco:
    def __init__(self, texto):
        self.texto = texto
        self.i = 0
    def __aiter__(self):
        return self
    async def __anext__(self):
        if self.i >= len(self.texto):
            raise StopAsyncIteration
        self.i += 1
        return self.texto[self.i - 1] * 2

async def main():
    async for p in Eco("oi"):
        print(p)

rodar(main())

