    def __init__(self, nome, raca):
        super().__init__(nome)
        self.raca = raca

c = Cachorro("Rex", "vira-lata")
print(c.nome, c.raca)

expr = compile("x * 2", "<conta>", "eval")
for x in range(3):
    print(eval(expr))
